namespace DbTools.Core;

/// <summary>1 mục trong cửa sổ Hướng dẫn. <paramref name="Keys"/>: phím / thao tác hiện thành các "phím" nhỏ.</summary>
public sealed record HelpItem(string Name, string Description, params string[] Keys);

/// <param name="PageTag">Tên trang (class trong DbTools.Views) mà mục này hướng dẫn - F1 trên trang đó mở thẳng mục này;
/// null = mục chung.</param>
public sealed record HelpSection(string Title, string Glyph, string Summary, string? PageTag, IReadOnlyList<HelpItem> Items);

/// <summary>Nội dung cửa sổ Hướng dẫn (F1). Mỗi trang có đúng 1 mục (unit test kiểm tra). Đổi tính năng thì cập nhật cả README.</summary>
public static class HelpContent
{
    public static IReadOnlyList<HelpSection> Sections { get; } =
    [
        new("Bắt đầu nhanh", "", "DbTools chạy cả thư mục script .sql lên PostgreSQL theo đúng thứ tự, trong 1 transaction: lỗi ở đâu là huỷ hết, DB không bị dở dang.", null,
        [
            new("1. Tạo kết nối", "Trang Kết nối → Thêm: host, port, database, user, mật khẩu → Thử kết nối. Tạo nhiều hồ sơ (dev, test...) để đổi nhanh."),
            new("2. Đọc thư mục", "Trang Chạy thư mục SQL → chọn thư mục chứa file .sql (kéo-thả thư mục vào trang cũng được) → Đọc thư mục. App tự sắp thứ tự chạy. Mỗi file tách thành từng câu theo dấu ; như psql (bỏ qua ; trong chuỗi, chú thích, thân hàm $$...$$ và thân hàm SQL chuẩn BEGIN ATOMIC ... END)."),
            new("3. Kiểm tra", "Đối chiếu với DB mà không thay đổi gì: đối tượng nào đã có (CREATE sẽ lỗi), file nào xoá / sửa dữ liệu, lệnh nào không chạy được."),
            new("4. Chạy thử", "Chạy thật mọi câu rồi ROLLBACK ở cuối: biết chắc script chạy được trên DB đó mà DB không đổi."),
            new("5. Chạy", "Hỏi lại (ghi rõ database đích), sao lưu những gì sẽ bị đổi (bật sẵn) rồi chạy trong 1 transaction và COMMIT. Lỗi ở câu nào: ROLLBACK toàn bộ, báo file + dòng lỗi."),
            new("Sao lưu / Khôi phục, Phiên kết nối", "Dump / Restore / Copy DB bằng pg_dump / pg_restore của máy (thư mục lưu mặc định D:\\DMP); xem và ngắt phiên đang kết nối."),
            new("Mở lại hướng dẫn này", "Mục Hướng dẫn cuối menu trái, nút ? hoặc phím F1 (mở thẳng phần của trang đang xem).", "F1"),
        ]),

        new("Chạy thư mục SQL", "", "Chạy mọi file .sql trong 1 thư mục (gồm thư mục con) lên database đang chọn.", "RunPage",
        [
            new("Thứ tự tự động", "Chạy theo vần ABC thường sai (CHECK / COMMENT chạy trước khi có bảng, view chạy trước bảng nó dùng). App sắp: file nhắc tới bảng / view / hàm do file khác tạo thì chạy sau file đó; file xoá dữ liệu bảng X (DELETE) chạy trước file thêm dữ liệu vào X (INSERT); còn lại theo loại: sequence → bảng → view → hàm → trigger → index / ràng buộc → comment → dữ liệu."),
            new("Schema", "Ô Schema cạnh ô database (nhớ theo từng hồ sơ kết nối; mở ô để chọn trong danh sách schema của DB hoặc gõ tên). Nút ✕ hoặc để trống = mặc định: theo search_path của server / user (thường là public). Chọn / gõ 1 schema = mọi lần Kiểm tra, Chạy thử, Chạy đặt search_path về schema đó: tên không ghi schema trong file (CREATE TABLE abc...) được tạo / tìm ở schema đã chọn; tên có ghi schema (CREATE TABLE s1.abc) vẫn theo file. Schema chưa có trong database → báo lỗi, không tự tạo (tránh chạy vào schema gõ nhầm tên)."),
            new("Tìm cả trong public", "Bật sẵn khi đã chọn schema: search_path = schema đã chọn, public - script dùng được bảng / hàm nền nằm ở public (vd bảng / hàm chung của mcframe), còn đối tượng mới vẫn tạo ở schema đã chọn. Tắt khi mọi thứ (cả bảng nền) nằm chung 1 schema."),
            new("Chỉnh thứ tự bằng tay", "Kéo dòng lên / xuống, hoặc chọn dòng rồi ▲ / ▼. Thứ tự chỉnh tay được nhớ theo thư mục (lần sau Đọc thư mục dùng lại; file mới xếp cuối). Sắp lại tự động = bỏ thứ tự đã nhớ.", "Kéo dòng"),
            new("Bỏ khỏi danh sách", "Không chạy 1 file (vd script tạm). Đọc lại thư mục vẫn bỏ qua file đó tới khi bấm Sắp lại tự động."),
            new("Cột Loại / Cảnh báo", "Loại = các loại lệnh trong file (Bảng, View, Hàm, Trigger, Comment...). Cảnh báo = file có DELETE / UPDATE / TRUNCATE / DROP (xoá / sửa dữ liệu hoặc đối tượng)."),
            new("Cột Kết quả", "Sau Kiểm tra: Đạt / số cảnh báo / lỗi. Sau Chạy: Đã chạy, Lỗi dòng N (kèm thông báo của PostgreSQL), Không chạy (file sau chỗ lỗi), Chạy được (đã rollback). Chọn 1 dòng để xem chi tiết ở ô dưới danh sách; Mở file để sửa."),
            new("Kiểm tra", "Chỉ đọc catalog của DB: CREATE TABLE / CREATE TRIGGER... mà đối tượng đã có → cảnh báo \"câu này sẽ lỗi\"; CREATE OR REPLACE đã có → thông tin \"sẽ được thay\". Không ghi gì vào DB."),
            new("Cảnh báo phụ thuộc", "Khi Kiểm tra / trước khi Chạy thử / Chạy: script có DROP TABLE, ALTER TABLE ... DROP COLUMN / ALTER COLUMN ... TYPE / RENAME COLUMN, đổi tên hoặc chuyển schema bảng (và các câu DROP của \"Xoá đối tượng cũ rồi tạo lại\") đụng bảng đang có trong DB → app tra đối tượng đang dùng bảng / cột đó (như tab Phụ thuộc ở Thông tin DB) và cảnh báo ngay trên dòng file + nhật ký + hộp hỏi lại: \"sẽ LỖI (rollback cả lô)\" khi view / khoá ngoại / hàm SQL chuẩn đang dùng (xoá bảng, xoá / đổi kiểu cột view dùng), \"CASCADE sẽ xoá kèm\" khi có CASCADE, \"hàm ... sẽ lỗi lúc chạy\" khi hàm nhắc tên bảng / cột (PostgreSQL vẫn cho chạy). Đổi tên bảng / cột: view và khoá ngoại tự theo tên mới, chỉ hàm bị ảnh hưởng. Đối tượng chính thư mục tạo lại thì không cảnh báo."),
            new("Chạy thử", "Chạy hết rồi ROLLBACK. Bắt được mọi lỗi thật (thiếu bảng nền, sai cú pháp, sai kiểu...) mà DB không đổi. Nên chạy thử trước mỗi lần chạy thật."),
            new("Chạy (1 transaction)", "BEGIN → mọi câu của mọi file → COMMIT. Câu nào lỗi hoặc bấm Huỷ → ROLLBACK, DB y như trước. PostgreSQL rollback được cả CREATE / DROP / ALTER. Trước khi chạy luôn hỏi lại, ghi rõ host:port/database, file xoá / sửa dữ liệu và bảng sẽ mất dữ liệu."),
            new("Xoá đối tượng cũ rồi tạo lại", "Để chạy lại script nhiều lần khi đang phát triển: trước khi chạy, xoá các đối tượng mà thư mục tạo ra (DROP ... IF EXISTS theo thứ tự ngược, không CASCADE), trong cùng transaction. DROP TABLE xoá luôn dữ liệu - Kiểm tra / hộp thoại hỏi lại báo bảng nào đang có dữ liệu."),
            new("Sao lưu trước khi chạy", "Bật sẵn (nhớ giữa các lần mở). Khi bấm Chạy (Chạy thử thì không): trước khi chạy, dump những gì đang có trong DB mà script sẽ đổi vào D:\\DMP\\TruocKhiChay\\<lúc chạy>_<db> (thư mục đổi ở trang Sao lưu / Khôi phục): bảng bị INSERT / UPDATE / DELETE / TRUNCATE / DROP hoặc bị xoá-rồi-tạo → bang-du-lieu.dump (cả dữ liệu); bảng / view / sequence bị thay hoặc thêm trigger / index / ràng buộc → cau-truc.dump (chỉ cấu trúc); hàm bị CREATE OR REPLACE, trigger bị tạo lại → ham-trigger.sql (bản cũ, chạy lại là trả về như trước). doc-ky.txt ghi có gì + lệnh lấy lại. Sao lưu lỗi (vd không có pg_dump) thì KHÔNG chạy. Thư mục chỉ tạo đối tượng mới thì bỏ qua sao lưu. Lịch sử chạy có nút Mở bản sao lưu."),
            new("Xem script xoá","Ghi script xoá ngược ra file .sql tạm (%TEMP%\\AppSuite\\DbTools) và mở ra để xem / chạy tay. Câu thêm / sửa / xoá dữ liệu không tự đảo ngược được - liệt kê cuối script để kiểm tra tay. Đã chọn schema thì bảng / view / hàm... trong script xoá ghi rõ schema (vd addon.app_order_all) - không xoá nhầm đối tượng cùng tên ở public."),
            new("Lệnh psql", "Dòng \\encoding UTF-8 đầu file được hiểu (đọc file theo encoding đó). Lệnh psql khác (\\i, \\set, \\connect...) báo lỗi - chạy file đó bằng psql. File tự BEGIN / COMMIT hoặc có lệnh không chạy được trong transaction (CREATE DATABASE, VACUUM, CREATE INDEX CONCURRENTLY) cũng báo lỗi."),
            new("Encoding", "File UTF-8 (có / không BOM) đọc thẳng. File không phải UTF-8 đọc theo Shift-JIS và tự chuyển sang UTF-8 khi gửi lên server - chạy được luôn, không cảnh báo (nhật ký ghi 1 dòng \"N file không phải UTF-8\"). Chỉ cảnh báo khi có byte không đọc được theo Shift-JIS (có thể là mã khác - mở file kiểm tra chữ Nhật / Việt), hoặc file gần như UTF-8 mà có vài byte hỏng (đọc theo UTF-8, byte hỏng thành �)."),
            new("Chuyển UTF-8", "Nút Chuyển UTF-8 (cạnh Mở file): tạo bản UTF-8 (không BOM) của các file Shift-JIS để mở / chạy bằng psql, DBeaver... - DbTools tự chạy không cần. Chọn 1 trong 3: lưu vào thư mục tạm (%TEMP%\\AppSuite\\DbTools\\UTF8\\<thư mục>_<giờ>), lưu vào <thư mục dump>\\UTF8\\<thư mục>_<giờ> (2 cách này chép kèm file đã là UTF-8, giữ thư mục con, file gốc không đổi), hoặc ghi đè file gốc (chỉ file không phải UTF-8; svn sẽ thấy file đã sửa - lấy lại bằng svn revert). Dòng \\encoding SJIS đổi thành \\encoding UTF8. Xong có nút Mở thư mục; app nhớ lựa chọn cho lần sau."),
            new("Nhật ký", "Ghi từng bước: kết nối, từng file (số câu, thời gian), NOTICE của server, lỗi kèm file + dòng, ROLLBACK / COMMIT. Copy nhật ký để gửi; mỗi lần chạy cũng lưu thành file log (trang Lịch sử chạy)."),
        ]),

        new("Sao lưu / Khôi phục", "\uE74E", "Dump database ra file, Restore từ file, Copy DB - thay cho các file bat pg_dump / pg_restore (mật khẩu không ghi rõ, có nhật ký + lịch sử).", "BackupPage",
        [
            new("Thư mục lưu file dump", "Mặc định D:\\DMP (nhớ giữa các lần mở; Chọn... để đổi, Mở để xem trong Explorer). Chưa có thì tự tạo khi Dump. Bản Sao lưu trước khi chạy nằm trong thư mục con TruocKhiChay."),
            new("PostgreSQL client", "App gọi pg_dump / pg_restore / psql của PostgreSQL cài trên máy. Tự động = bản mới nhất tìm thấy trong Program Files\\PostgreSQL\\*\\bin và PATH (bản mới đọc được server / file dump cũ hơn; pg_dump cũ hơn server thì bị từ chối - app báo trước). Thư mục bin... = chọn tay (vd bản cài riêng D:\\PostgreSQL12_9\\...\\bin). Mật khẩu lấy từ hồ sơ kết nối, truyền qua biến môi trường PGPASSWORD - không nằm trên dòng lệnh, không ghi vào log."),
            new("Dump", "Chọn server (hồ sơ kết nối) + database (mở ô để chọn trong danh sách DB của server, hoặc gõ). Kiểu Custom (.dump, nén, restore chọn lọc được - khuyên dùng) hoặc SQL thường (.sql, đọc / sửa được bằng tay). Tuỳ chọn chỉ cấu trúc (-s), chỉ 1 schema (-n). File đặt tên <db>_yyyyMMdd_HHmm.dump trong thư mục lưu dump, kèm file .log cùng tên. Lỗi thì xoá file dở dang."),
            new("Restore - chọn file", "Chọn... hoặc gõ đường dẫn rồi Xem nội dung: app đọc file (pg_restore -l) và báo DB gốc, lúc dump, bản PostgreSQL, số bảng / bảng có dữ liệu / view / hàm..., schema, owner. File .sql (dump SQL thường) chạy bằng psql."),
            new("Restore - đích", "Tạo DB mới: tên chưa có trên server → CREATE DATABASE trống (template0) rồi restore vào. Ghi vào DB có sẵn: database phải có rồi; bật Xoá đối tượng trùng tên trước (--clean --if-exists) để xoá bảng / hàm trùng tên với file dump (mất cả dữ liệu) rồi tạo lại, không bật thì đối tượng trùng tên báo lỗi \"already exists\". Không có chức năng xoá cả database (quá nguy hiểm) - cần thì restore vào tên mới."),
            new("Restore - tuỳ chọn", "Lỗi là huỷ hết (bật sẵn): chạy trong 1 transaction, lỗi ở đâu là rollback hết, DB đích không dở dang (DB mới tạo thì còn trống - xoá tay nếu không dùng). Bỏ owner / quyền: khi user trên server đích khác user gốc (hộp thoại hỏi lại báo nếu owner trong file dump khác user đích). Luôn hỏi lại trước khi restore, nút mặc định là Huỷ."),
            new("Copy DB", "Cùng server (cùng host + port): CREATE DATABASE <mới> TEMPLATE <nguồn> - chép nguyên khối, rất nhanh; DB nguồn không được có phiên nào khác đang kết nối: có thì hộp thoại báo số phiên + ai đang dùng, bấm \"Ngắt phiên rồi copy\" để ngắt rồi copy. Khác server: pg_dump nguồn ra file tạm trong thư mục lưu dump → tạo DB mới trên server đích → pg_restore (1 transaction) → xoá file tạm. Tên DB mới gợi ý <nguồn>_copy_yyyyMMdd, tên đã có thì báo lỗi (không ghi đè)."),
            new("Xem lệnh", "Nút cạnh Dump / Restore / Copy: xem trước các bước sẽ chạy với lựa chọn hiện tại (chưa chạy gì), dạng file .bat: câu kiểm tra chỉ đọc, CREATE DATABASE, ngắt phiên (chỉ khi bấm Ngắt phiên rồi copy), dòng pg_dump / pg_restore / psql đủ tham số. Câu SQL app chạy qua kết nối riêng được viết thành psql -c để chạy tay được. Mật khẩu không hiện - dòng set PGPASSWORD=<mật khẩu của hồ sơ ...> để tự điền. Copy = chép cả script; dán vào file .bat, điền mật khẩu là chạy được trong cmd. Tên file dump theo giờ lúc bấm nên có thể lệch vài phút so với lúc chạy thật."),
            new("Nhật ký / Huỷ", "Nhật ký hiện lệnh đã chạy (không có mật khẩu) và mọi dòng pg_dump / pg_restore in ra. Huỷ = dừng tiến trình đang chạy (restore 1 transaction thì không đổi gì). Mỗi lần Dump / Restore / Copy được ghi vào Lịch sử chạy kèm file log."),
        ]),

        new("Thông tin DB", "", "Tra cứu cấu trúc database thay DBeaver: tổng quan, bảng (cột, index, ràng buộc, trigger, DDL), view / hàm / trigger / sequence / extension. Chỉ đọc catalog, không thay đổi gì.", "DbInfoPage",
        [
            new("Đọc", "Chọn server (hồ sơ kết nối) + database (mở ô để chọn trong danh sách DB của server, hoặc gõ) → Đọc. Đọc 1 lần cả danh sách bảng / đối tượng; DB vừa đổi (chạy script, restore) thì bấm Đọc lại."),
            new("Tổng quan", "Bản PostgreSQL, dung lượng DB, encoding / collate, owner, server chạy từ lúc nào, số phiên đang kết nối, tổng số bảng / view / hàm / trigger / sequence / extension; bảng theo schema: owner, số đối tượng từng loại, dung lượng."),
            new("Lọc", "Tab Bảng và Đối tượng khác: chọn 1 schema hoặc (Tất cả schema), gõ một phần tên (không phân biệt hoa / thường, gõ được cả schema.tên). Bảng sắp được theo tên, dung lượng (tìm bảng to) hoặc số dòng."),
            new("Bảng", "Mỗi dòng: schema.tên (kèm phân vùng / bảng ngoài), số dòng, dung lượng (bảng + index + TOAST), số cột, có khoá chính (✓) không, ghi chú (COMMENT). Rê chuột: dung lượng bảng / index, lần VACUUM / ANALYZE gần nhất."),
            new("Số dòng ≈", "Số dòng mặc định là ước lượng theo thống kê của server (nhanh, có thể lệch nếu bảng chưa ANALYZE). Đếm chính xác = SELECT count(*) các bảng đang hiện (lọc trước cho ít bảng - bảng lớn có thể lâu); trong chi tiết bảng có nút Đếm dòng chính xác.", "Đếm chính xác"),
            new("Chi tiết bảng", "Bấm đúp / Enter / Xem chi tiết. Cột: số thứ tự, tên, kiểu (độ dài / số lẻ), NOT NULL, mặc định (cả identity, cột tính), khoá (PK, FK → bảng(cột)), ghi chú. Index: tên, khoá chính / duy nhất, dung lượng, câu CREATE INDEX. Ràng buộc: khoá chính, duy nhất, khoá ngoại (ON DELETE...), check. Trigger: bật / ĐANG TẮT, hàm, câu CREATE TRIGGER. ← Danh sách bảng để quay lại.", "Bấm đúp", "Enter"),
            new("Phụ thuộc (xoá / sửa bảng ảnh hưởng tới đâu)", "Tab cuối của chi tiết bảng. Dòng Ảnh hưởng ở trên: DROP TABLE có bị chặn không, DROP ... CASCADE sẽ xoá / bỏ gì, gì bị xoá theo bảng, hàm nào sẽ lỗi lúc chạy, cột nào đang dùng trong view (đổi kiểu / xoá cột đó sẽ báo lỗi). Danh sách: View (cả view dựng trên view đó - ghi \"gián tiếp qua\"; kèm cột view dùng), Khoá ngoại từ bảng khác, Trigger và Sequence của bảng (xoá theo bảng), Hàm SQL chuẩn (BEGIN ATOMIC) - cột Nguồn \"catalog\" = PostgreSQL ghi nhận, chắc chắn. Hàm (mã nguồn) = hàm / procedure có nhắc tên bảng trong thân hàm (bỏ qua chú thích, có đọc SQL động trong '...'; \"theo tên\" = không ghi schema, đúng khi search_path tìm tới) và Trigger khác = trigger trên bảng khác gọi các hàm đó - cột Nguồn \"dò mã nguồn\" vì PostgreSQL không theo dõi thân hàm plpgsql. Chọn 1 dòng → ô dưới hiện định nghĩa / các dòng nhắc tới bảng."),
            new("DDL", "CREATE TABLE dựng lại từ catalog (PostgreSQL không có sẵn lệnh lấy DDL bảng) theo thứ tự như pg_dump: CREATE TABLE → ALTER TABLE ADD CONSTRAINT (khoá ngoại sau cùng) → CREATE INDEX → CREATE TRIGGER (+ DISABLE TRIGGER nếu đang tắt) → COMMENT ON. Copy DDL để dán vào script / so với file svn. Không gồm GRANT, owner, giá trị sequence."),
            new("Sinh dữ liệu mẫu", "Nút trong chi tiết bảng: mở trang Sinh dữ liệu mẫu với bảng đó, lấy vài dòng đầu làm mẫu."),
            new("Đối tượng khác", "View (cả materialized), Hàm / procedure (tham số → kiểu trả về · ngôn ngữ), Trigger (trên bảng nào → hàm nào, ĐANG TẮT), Sequence (giá trị hiện tại), Extension (bản). Chọn 1 dòng → định nghĩa ở ô dưới: CREATE OR REPLACE VIEW / FUNCTION, CREATE TRIGGER, CREATE SEQUENCE, CREATE EXTENSION; Copy để chép."),
            new("Tìm trong mã nguồn", "Tab cuối của Đối tượng khác: gõ chữ (tên bảng, cột, câu báo lỗi...) → Tìm hoặc Enter: tìm trong định nghĩa mọi view / materialized view / hàm / procedure (cả chú thích). Cả từ = không khớp khi chữ là 1 phần của tên dài hơn (order ≠ order_detail); Phân biệt hoa thường tắt sẵn. Kết quả: số chỗ khớp + dòng đầu tiên; ô Schema / Tìm theo tên ở trên lọc thêm. Chọn 1 dòng → ô Định nghĩa bôi đen chỗ khớp đầu tiên, thanh trạng thái ghi các số dòng. Mã nguồn đọc 1 lần sau mỗi lần Đọc.", "Enter"),
        ]),

        new("Chạy SQL", "", "Chạy nhanh vài câu SQL lên 1 hồ sơ kết nối, xem kết quả dạng bảng. Mặc định chỉ đọc: không câu nào ghi được vào DB.", "QueryPage",
        [
            new("Chạy", "Gõ câu vào ô soạn → Chạy. Có chọn (bôi đen) 1 đoạn thì chỉ chạy đoạn đó, không chọn thì chạy cả ô. Nhiều câu cách nhau bằng dấu ; (tách như psql: bỏ qua ; trong chuỗi, chú thích, thân hàm $$...$$), chạy lần lượt trong cùng 1 giao dịch. Chạy theo hồ sơ đang chọn: database + schema (search_path) của hồ sơ đó.", "Ctrl+Enter", "F5"),
            new("Chỉ đọc (mặc định)", "BEGIN READ ONLY ... ROLLBACK: INSERT / UPDATE / DELETE / CREATE / DROP / nextval... đều bị PostgreSQL từ chối (lỗi 25006), DB không đổi. Dùng được cho cả hồ sơ Production. BEGIN / COMMIT / ROLLBACK / SET TRANSACTION gõ trong ô bị chặn (DbTools tự mở / đóng giao dịch); SAVEPOINT vẫn được."),
            new("Cho phép ghi", "Bật công tắc: BEGIN ... COMMIT. Trước khi chạy hỏi lại (server, schema, các câu sẽ chạy); hồ sơ Production phải gõ lại tên database. Mọi câu chạy được thì COMMIT; câu nào lỗi hoặc bấm Huỷ thì ROLLBACK hết. Đổi server là công tắc tự tắt. VACUUM, CREATE INDEX CONCURRENTLY, CREATE DATABASE không chạy được trong giao dịch - dùng psql."),
            new("Bảng kết quả", "Hiện kết quả của câu trả về dòng cuối cùng (SELECT, INSERT ... RETURNING, SHOW, EXPLAIN...). Tiêu đề cột ghi tên + kiểu; NULL hiện chữ NULL mờ nghiêng; ô nhiều dòng hiện dòng đầu + ⏎… (rê chuột xem đủ). Bảng cuộn ngang / dọc, chỉ dựng các dòng đang hiện. Thời gian theo giờ máy này (timestamptz kèm độ lệch, vd +07)."),
            new("Đọc tối đa", "100 / 1.000 (mặc định) / 10.000 dòng / Tất cả, nhớ cho lần sau. SELECT đọc qua cursor nên chỉ lấy đúng số dòng này về máy, bảng lớn vẫn nhanh; còn dòng chưa đọc thì dòng trạng thái ghi \"còn nữa\". Tất cả: bảng lớn sẽ chậm và tốn bộ nhớ - muốn lấy đủ thì Xuất CSV."),
            new("Thông báo", "Thẻ cạnh Kết quả: từng câu đã chạy (dòng, loại câu, số dòng, thời gian), NOTICE / WARNING của server (vd RAISE NOTICE trong DO), lệnh psql \\xxx bị bỏ qua. Lỗi: dòng của câu lỗi + thông báo của PostgreSQL, tự chuyển sang thẻ này."),
            new("Huỷ / giới hạn thời gian", "Nút Huỷ dừng câu đang chạy và rollback. Mỗi câu chạy tối đa 60 giây (statement_timeout, đổi ở trang Cài đặt, 0 = không giới hạn)."),
            new("Chép", "Chép dòng đã chọn (Ctrl / Shift + bấm để chọn nhiều, Ctrl+C trong bảng) hoặc Chép cả bảng: kèm tiêu đề, cột cách nhau Tab - dán thẳng vào Excel / CsvEditor. Chuột phải 1 ô: Chép ô này, chép dòng không kèm tiêu đề.", "Ctrl+C"),
            new("Xuất CSV", "Đủ mọi dòng (không theo Đọc tối đa) → <thư mục dump>\\ChaySql\\<hồ sơ>_<lúc>.csv (UTF-8 có BOM), mở bằng CsvEditor nếu có trong bộ AppSuite. Đã đọc hết thì ghi luôn bảng đang có; còn dòng chưa đọc thì chạy lại câu cuối đó trong giao dịch chỉ đọc (câu ghi dữ liệu không chạy lại được)."),
            new("Lịch sử", "Nút Lịch sử: 200 câu chạy gần nhất (giờ, hồ sơ, GHI nếu chạy ở chế độ ghi, số dòng / lỗi, thời gian), ô tìm theo chữ trong câu / hồ sơ / server. Bấm 1 câu để nạp lại vào ô soạn. Chạy lại đúng câu đó trên cùng server thì đưa lên đầu. Lưu ở Data\\History\\queries.json. Ô soạn tự nhớ nội dung khi rời trang / đóng app."),
        ]),

        new("Sinh dữ liệu mẫu", "", "Từ vài dòng mẫu của 1 bảng (trong DB hoặc file CSV) sinh thêm nhiều dòng giả ra file CSV và / hoặc INSERT. Không ghi gì vào DB.", "MockDataPage",
        [
            new("Nguồn mẫu", "Bảng trong DB: chọn server, database, bảng (mở ô để chọn, hoặc gõ schema.bảng), số dòng mẫu → Đọc mẫu: app biết kiểu cột, NOT NULL, khoá chính / duy nhất, khoá ngoại, cột DB tự sinh. File CSV mẫu: dòng đầu là tên cột (UTF-8 / Shift-JIS, dấu phẩy hoặc tab), kiểu đoán từ giá trị; Tên bảng cho INSERT (trống = tên file). Từ trang Thông tin DB → chi tiết bảng → Sinh dữ liệu mẫu cũng mở thẳng trang này."),
            new("Cách sinh từng cột", "App đề xuất theo kiểu + khoá + mẫu, chỉnh được: Bỏ qua (DB tự sinh - identity, serial, cột tính), Tăng dần (số: 1001, 1002...; mã: ORD000124, ORD000125... giữ tiền tố và số chữ số; bảng trong DB thì bắt đầu sau giá trị lớn nhất đang có), Số ngẫu nhiên (min..max, đúng số lẻ của numeric), Ngày ngẫu nhiên (yyyy-MM-dd..yyyy-MM-dd, mặc định ±30 ngày quanh mẫu), Chọn trong danh sách (A|B|C - cờ, mã ngắn, giá trị lặp lại), Mẫu chuỗi {n} (khách {n} → khách 1, khách 2...), Giữ nguyên, NULL, true / false, UUID, Khoá ngoại (chọn ngẫu nhiên trong giá trị đang có ở bảng được tham chiếu - tối đa 5000 giá trị)."),
            new("Kiểm tra", "Khi sinh: NOT NULL không để NULL; chuỗi không dài quá varchar(n) / char(n); số không vượt numeric(p,s); khoá chính / duy nhất không trùng trong file (Mẫu chuỗi {n} không so với dữ liệu đang có trong DB - Tăng dần thì có). Lỗi → báo cột + giá trị, không ghi file nào."),
            new("Xem trước", "20 dòng đầu dạng CSV - đúng 20 dòng đầu của file khi Sinh file (cùng bộ ngẫu nhiên tới khi Đọc mẫu lại)."),
            new("Đầu ra", "Số dòng (1 - 1.000.000), CSV và / hoặc SQL INSERT, encoding CSV (UTF-8 có BOM cho Excel / UTF-8 / Shift-JIS), dòng tiêu đề, NULL là ô trống hay chữ NULL, thư mục lưu (mặc định <thư mục dump>\\DuLieuMau) - đều nhớ cho lần sau. File <bảng>_<số dòng>dong_<lúc sinh>.csv / .sql. INSERT 500 dòng / câu, không BEGIN / COMMIT: chạy bằng trang Chạy thư mục SQL (1 transaction) hoặc psql. Cột Bỏ qua không có trong file."),
        ]),

        new("Phiên kết nối", "\uE716", "Ai đang kết nối vào database nào; ngắt phiên trước khi copy DB / restore, hoặc gỡ phiên treo đang giữ khoá.", "SessionsPage",
        [
            new("Làm mới", "Đọc pg_stat_activity: PID, database, user · ứng dụng (vd DBeaver, pgAdmin, AppSuite DbTools), máy kết nối, trạng thái (đang chạy / rảnh / rảnh trong transaction...), lúc kết nối, câu gần nhất (rê chuột để xem đủ). Ô Database lọc theo 1 DB; nút ✕ = mọi DB trên server. Phiên \"(DbTools)\" là phiên app dùng để đọc danh sách - không ngắt."),
            new("Ai chặn ai", "Cột Chờ / chặn: ⛔ chờ khoá, bị PID x chặn (chữ đỏ) - phiên này đứng chờ vì phiên x giữ khoá (dòng / bảng) nó cần; 🔒 đang chặn N phiên (chữ cam). Không bị chặn mà đang chờ việc khác thì ghi loại chờ (vd IO / DataFileRead). Dòng trạng thái đếm số phiên bị chặn. Chọn 1 phiên bị chặn: ô chi tiết bên dưới ghi phiên đầu chuỗi đang chặn (user, ứng dụng, máy, transaction mở bao lâu, câu của nó) và khoá đang chờ (vd ShareLock trên transaction, RowExclusiveLock trên bảng x)."),
            new("Chạy bao lâu", "Dòng trên: câu đang chạy được bao lâu (chỉ khi đang chạy); dòng dưới: transaction đang mở bao lâu (tx ...). Phiên \"rảnh trong transaction\" lâu = quên COMMIT / ROLLBACK, hay là thủ phạm giữ khoá."),
            new("Chỉ phiên đang chạy / chặn / bị chặn", "Ẩn phiên rảnh, giữ phiên đang chạy câu, đang chặn hoặc bị chặn (kể cả phiên rảnh trong transaction đang chặn người khác). Phiên DbTools dùng để đọc danh sách cũng ẩn."),
            new("Tự làm mới", "Ô tích Tự làm mới mỗi 5 giây (tắt sẵn): đọc lại danh sách, giữ các dòng đang chọn. Rời trang, đổi server hoặc lỗi kết nối thì tự tắt; đang mở hộp hỏi lại thì bỏ lượt."),
            new("Huỷ câu đang chạy", "pg_cancel_backend các phiên đã chọn: chỉ câu đang chạy bị dừng (ứng dụng nhận lỗi \"canceling statement due to user request\"), transaction đang mở bị rollback, phiên vẫn kết nối. Phiên không có câu đang chạy (rảnh / rảnh trong transaction) thì huỷ câu không có tác dụng - hộp hỏi lại có cảnh báo. Hồ sơ Production phải gõ tên database."),
            new("Gỡ kẹt khoá", "Chọn phiên bị chặn → Huỷ câu của phiên đang chặn (phiên đầu chuỗi đang chạy câu dài) hoặc Ngắt phiên đang chặn (phiên rảnh trong transaction - huỷ câu không gỡ được). Xong thì phiên bị chặn tự chạy tiếp."),
            new("Ngắt phiên", "Chọn 1 hoặc nhiều dòng (Ctrl / Shift + bấm) → Ngắt phiên đã chọn; Ngắt hết = mọi phiên trong danh sách. Luôn hỏi lại. Phiên bị ngắt: câu đang chạy bị huỷ, transaction chưa COMMIT bị rollback, ứng dụng đó mất kết nối. Cần quyền superuser / pg_signal_backend, hoặc cùng user với phiên đó."),
            new("Khi nào cần", "\"database is being accessed by other users\" khi copy DB bằng TEMPLATE / xoá DB; restore / chạy script bị treo chờ khoá vì 1 phiên \"rảnh trong transaction\" đang giữ bảng."),
        ]),
        new("Nhật ký server", "", "Đọc file log của server PostgreSQL qua SQL (chỉ đọc, không đổi gì trên server): ai chạy câu gì, lúc nào, từ máy nào, lỗi gì.", "ServerLogPage",
        [
            new("Làm mới", "Đọc cấu hình log của server, danh sách file trong thư mục log, rồi đọc luôn file server đang ghi. Không cần vào máy server: đọc bằng pg_ls_logdir / pg_read_binary_file - cần superuser, hoặc role pg_monitor (danh sách file) + pg_read_server_files (nội dung)."),
            new("Cấu hình log", "Nút cạnh tiêu đề (vd \"Cấu hình log: log_statement = all, 7 file, 10 KB · 1 lưu ý\"), bấm để xem bằng lời: server ghi những câu nào (log_statement: none / ddl / mod / all, câu chạy lâu theo log_min_duration_statement), đầu dòng log có đủ giờ / user / database / máy / ứng dụng không (log_line_prefix), giữ log bao lâu (vd tên file theo thứ trong tuần = chỉ giữ 7 ngày, tuần sau ghi đè), đủ quyền đọc không. ⚠ = cần lưu ý. Muốn đổi cấu hình phải nhờ DBA - DbTools không sửa."),
            new("Đọc file", "Chọn file (mới sửa nhất ở trên, \"đang ghi\" = file hiện tại) và đọc 2 / 10 / 50 MB cuối hoặc cả file → Đọc file. Bấm lại để thấy dòng mới. Đọc giữa file thì bỏ dòng đầu của đoạn (có thể bị cắt dở)."),
            new("Theo dõi", "Nút Theo dõi (cạnh Đọc file): đọc file server đang ghi rồi mỗi 2 giây đọc tiếp phần mới, dòng mới hiện cuối bảng, bộ lọc vẫn áp. Bảng tự cuộn xuống dòng mới nếu đang ở cuối - cuộn lên xem dòng cũ thì đứng yên. Server sang file mới (qua ngày, file quá lớn) thì tự đọc sang. Giữ 1 kết nối suốt lúc theo dõi; bấm Dừng theo dõi, chọn file khác, đổi server hoặc rời trang là dừng và đóng kết nối. Mất kết nối thì báo ở chân trang và tự thử lại."),
            new("Dung lượng log", "Nút Cấu hình log có dòng Dung lượng thư mục log: tổng, file lớn nhất, tăng khoảng bao nhiêu / ngày (theo các file sửa trong 7 ngày qua). ⚠ khi tổng vượt ngưỡng (mặc định 1 GB, đổi ở Cài đặt), hoặc khi server không tự xoá file cũ mà theo tốc độ này dưới 30 ngày nữa sẽ vượt. DbTools không biết ổ đĩa máy server còn trống bao nhiêu."),
            new("Bảng", "Mỗi dòng: giờ, loại (SELECT / INSERT / UPDATE / DELETE / DDL / SQL khác / Lỗi / Kết nối / Server), user · database, máy (IP và cổng) · ứng dụng, thời gian chạy (ms), câu SQL. Câu nhiều dòng được ghép lại; dòng \"duration\" ghép vào câu của nó; DETAIL (vd tham số $1 của câu ứng dụng gửi) và STATEMENT của lỗi ghép vào dòng tương ứng. WITH ... theo lệnh chính sau các CTE (WITH x AS (DELETE ...) INSERT ... là INSERT); lệnh chính là SELECT mà CTE có xoá / sửa thì theo lệnh ghi đó (không bị lẫn vào SELECT), TRUNCATE tính là DELETE, MERGE là UPDATE. Chọn 1 dòng xem đủ ở ô chi tiết bên dưới (chọn / chép được). Bấm tiêu đề cột Giờ để đổi cũ nhất trước (↑, thứ tự trong file) ↔ mới nhất trước (↓), app nhớ cho lần sau; Theo dõi khi xếp mới trước thì dòng mới chèn lên đầu. Không chia trang: bảng chỉ dựng các dòng đang hiện nên vài trăm nghìn dòng vẫn cuộn mượt. Xuất CSV theo thứ tự đang hiện, Xuất TXT luôn theo thứ tự thời gian như file log."),
            new("Lọc theo giờ (Từ / Đến)", "2 ô ở hàng lọc. Gõ 14:02, 14:02:30, 11-26 14:02, 2026-11-26 14:02 hoặc 2026-11-26 (chỉ ngày = cả ngày). Chỉ gõ giờ thì lấy ngày của dòng log mới nhất đã đọc. Từ gồm cả mốc; Đến gồm cả phút / giây của mốc (Đến 14:02 gồm 14:02:59). Chỉ điền Từ = sau giờ đó, chỉ điền Đến = trước giờ đó; trống = không giới hạn. Gõ sai cách thì ô viền đỏ, chân trang gợi ý cách gõ và ô đó tạm bỏ qua. Chỉ lọc trong phần đã đọc (vd 2 MB cuối): mốc Từ trước phần đã đọc thì chân trang nhắc chọn đọc nhiều hơn / cả file."),
            new("Chép tên bảng", "Nút ở chân trang, lấy các dòng đang hiện (sau mọi bộ lọc), chỉ câu INSERT / UPDATE / DELETE (cả MERGE, TRUNCATE, WITH ... INSERT - lấy lệnh chính, không lấy lệnh trong CTE; chữ trong chuỗi / chú thích không tính). Theo thứ tự: mỗi bảng của mỗi câu 1 dòng \"giờ ⇥ lệnh ⇥ bảng\" theo thứ tự chạy (kể cả khi bảng đang xếp mới nhất trước). Không trùng: mỗi bảng 1 dòng \"bảng ⇥ các lệnh ⇥ số câu\" theo lần đầu xuất hiện (không phân biệt hoa thường). Dán Excel thành cột. Tên giữ như trong câu (cả schema), bỏ dấu \"; TRUNCATE a, b ra 2 bảng."),
            new("Chép SQL", "2 nút cạnh ô chi tiết. Chép SQL: đúng câu SQL của dòng đang chọn (không kèm giờ, DETAIL). Chép SQL đã thay tham số (chỉ bật khi log có dòng parameters): câu ứng dụng gửi kiểu $1, $2... được thay bằng giá trị log ghi ('...' hoặc NULL), dòng có thay kèm chú thích cuối dòng -- $1 = '...' (giá trị dài thì chú thích cắt bớt, câu vẫn đủ). $1 nằm trong chuỗi '...', chú thích, tên \"...\" hay thân $$...$$ thì giữ nguyên. Dán vào trang Chạy SQL / psql để chạy thử. Log không ghi đủ giá trị (bị cắt theo log_parameter_max_length) thì chân trang báo $n nào giữ nguyên."),
            new("Lọc / tìm", "Ô tìm: chữ trong câu SQL / thông báo / chi tiết; ô User, Database, Máy / IP / ứng dụng: chứa chữ đó (không phân biệt hoa thường). Nút Loại: ô tích từng loại kèm số dòng (mặc định bỏ Kết nối và Server) và ô Ẩn câu của DbTools (bật sẵn): câu DbTools chạy để đọc log cũng bị server ghi lại khi log_statement = all."),
            new("Xuất CSV / TXT", "Các dòng đang hiện → <thư mục dump>\\NhatKyServer\\<hồ sơ>_<file>_<lúc>.csv (mở bằng CsvEditor nếu có trong bộ AppSuite) hoặc .txt (đúng nguyên văn log). Dùng để giữ log lâu hơn số ngày server giữ. Mật khẩu (PASSWORD '...') luôn được che, nhưng file vẫn có nguyên câu SQL - cẩn thận khi gửi ra ngoài."),
            new("Đổi cấu hình log", "Nút Cấu hình log → Đổi cấu hình (trang Cấu hình server): mở trang Cấu hình server ở nhóm Log, cùng server đang xem - đổi log_statement, log_min_duration_statement, log_connections / log_disconnections, log_line_prefix... rồi Áp dụng. Xem xong nhớ Về mặc định nếu đã bật ghi mọi câu."),
            new("Không đọc được", "\"must be superuser\" / permission denied: user thiếu quyền - dùng hồ sơ superuser hoặc nhờ DBA cấp pg_monitor + pg_read_server_files. Nhiều \"dòng không nhận ra định dạng\": lc_messages không phải tiếng Anh. File .csv / .json (csvlog / jsonlog) chưa hỗ trợ. logging_collector = off: log không ghi ra file, không đọc được qua SQL."),
        ]),
        new("Cài đặt", "", "Thiết lập dùng cho mọi trang: thời gian chờ kết nối, thư mục dump, PostgreSQL client, Sao lưu trước khi chạy, thư mục dữ liệu của DbTools. Sửa là lưu ngay.", "SettingsPage",
        [
            new("Chạy SQL", "Mỗi câu ở trang Chạy SQL chạy tối đa bao nhiêu giây (mặc định 60, 0 = không giới hạn, tối đa 3600): quá thì dừng câu đó và rollback."),
            new("Thời gian chờ kết nối", "5 - 120 giây (mặc định 15), áp cho mọi hồ sơ và mọi trang. Server qua VPN / mạng chậm hay báo \"Hết thời gian chờ kết nối\" thì tăng lên. Các thao tác đọc nhanh (danh sách database, phiên...) tự chờ ít nhất bằng thời gian này + 10 giây. Sai host / port thì phải chờ hết thời gian này mới báo lỗi - Thử kết nối có nút Huỷ."),
            new("Thư mục dump", "Nơi ghi file Dump, file tạm khi Copy DB khác server, bản Sao lưu trước khi chạy (TruocKhiChay), Dữ liệu mẫu (DuLieuMau), file xuất Nhật ký server (NhatKyServer). Cùng giá trị với ô ở trang Sao lưu / Khôi phục - sửa ở đâu cũng được."),
            new("PostgreSQL client", "Thư mục bin có pg_dump / pg_restore / psql. Trống (nút Tự động) = bản mới nhất tìm được trên máy; dòng bên dưới cho biết bản sẽ dùng. Dump server mới hơn client thì pg_dump lỗi - chọn client cùng hoặc mới hơn server."),
            new("Sao lưu trước khi chạy", "Bật / tắt mặc định cho trang Chạy thư mục SQL (cùng ô ở trang đó)."),
            new("Nhật ký server", "Ngưỡng cảnh báo dung lượng thư mục log của server (MB, mặc định 1024): vượt thì nút Cấu hình log trên trang Nhật ký server báo ⚠."),
            new("Dữ liệu của DbTools", "Thư mục Data cạnh DbTools.exe: Config\\connections.json (hồ sơ kết nối, mật khẩu mã hoá theo tài khoản Windows - chép sang máy / tài khoản khác phải nhập lại), Config\\settings.json, History (lịch sử chạy + log). Nút Mở thư mục."),
        ]),

        new("Cấu hình server", "", "Xem và đổi mọi thông số của server PostgreSQL (pg_settings). Đổi = ALTER SYSTEM + nạp lại cấu hình: áp cho CẢ SERVER (mọi database). Cần superuser.", "ServerConfigPage",
        [
            new("Làm mới", "Chọn server (hồ sơ) → Làm mới: đọc mọi thông số (khoảng 350), xếp theo nhóm - Log đầu tiên, rồi Kết nối, Tài nguyên (bộ nhớ, đĩa), Mặc định cho phiên, Tối ưu câu lệnh, WAL, Autovacuum, Khoá... Mỗi dòng: tên, mô tả ngắn, giá trị đang áp (dạng dễ đọc, vd 128MB, 1min)."),
            new("Tìm / lọc", "Ô Nhóm, ô Tìm (tên / mô tả; nhiều từ phải có đủ) và các ô lọc: Khác mặc định (đặt trong file cấu hình, dòng lệnh hoặc ALTER SYSTEM), ● ALTER SYSTEM (đặt trong postgresql.auto.conf - Về mặc định được), ↻ Cần khởi động lại, ⚑ Đặt riêng DB / user (ALTER DATABASE / ROLE ... SET đè lên cấu hình server). Dấu cạnh tên: ✎ chờ áp dụng, ● ALTER SYSTEM, ↻ cần khởi động lại, ◆ đã ghi giá trị mới đang chờ khởi động lại, ⚑ đặt riêng."),
            new("Chi tiết", "Chọn 1 dòng: mô tả đầy đủ, nhóm, giá trị đang áp, mặc định, nguồn (file + dòng; chỉ superuser thấy), áp dụng khi nào (nạp lại là có hiệu lực / chỉ kết nối mới / cần khởi động lại / chỉ xem), giá trị cho phép (khoảng min - max kèm đơn vị, hoặc danh sách), các chỗ đặt riêng theo database / user. Giá trị \"đang áp\" đọc trong phiên của DbTools (database bảo trì postgres, user của hồ sơ): thông số ⚑ đặt riêng cho database / user đó thì hiện giá trị đặt riêng chứ không phải giá trị chung của server."),
            new("Sửa", "Gõ giá trị mới (số có thể kèm đơn vị: kB / MB / GB, ms / s / min / h / d) hoặc chọn on / off / giá trị trong danh sách → Đổi (hoặc Enter): vào danh sách chờ áp dụng ở chân trang, dòng hiện \"cũ → mới\" màu cam. Sửa nhiều thông số rồi áp dụng 1 lần. Giá trị sai kiểu / ngoài khoảng báo ngay, chưa gửi gì lên server. Bỏ = bỏ thay đổi của dòng đó; Bỏ hết = bỏ mọi thay đổi chờ.", "Enter"),
            new("Áp dụng", "Hộp hỏi lại ghi rõ từng thông số cũ → mới, câu sẽ chạy và lưu ý (cần khởi động lại, đang đặt riêng theo database / user, ghi mọi câu làm log lớn nhanh); hồ sơ Production phải gõ lại tên database. DbTools chạy ALTER SYSTEM SET từng thông số (ghi vào postgresql.auto.conf trên máy server) rồi pg_reload_conf() và đọc lại: dòng trạng thái báo giá trị mới. Câu nào lỗi thì dừng, các câu trước đã ghi, phần còn lại giữ ở danh sách chờ."),
            new("Cần khởi động lại", "Thông số ↻ (shared_buffers, max_connections, logging_collector...): Áp dụng chỉ ghi giá trị vào file, server vẫn chạy giá trị cũ (dấu ◆) tới khi khởi động lại - DbTools không tự khởi động lại. Giá trị sai có thể làm server không lên được: muốn bỏ thì Về mặc định → Áp dụng trước khi khởi động lại."),
            new("Về mặc định", "Thông số ● (đặt bằng ALTER SYSTEM): Về mặc định = ALTER SYSTEM RESET (bỏ dòng trong postgresql.auto.conf), server quay về giá trị trong postgresql.conf hoặc mặc định. Về mặc định tất cả = mọi thông số ●. Cũng phải bấm Áp dụng. Thông số đặt trong postgresql.conf thì DbTools không sửa file đó."),
            new("Quyền", "Cần superuser (PostgreSQL 15+: hoặc được GRANT ALTER SYSTEM ON PARAMETER). User thường vẫn xem được (không thấy nguồn file); Áp dụng sẽ báo lỗi 42501, server không đổi. Đặt riêng theo database / user chỉ xem được ở đợt này."),
            new("Từ Nhật ký server", "Nút Cấu hình log → Đổi cấu hình: mở trang này ở nhóm Log, cùng server đang xem."),
        ]),

        new("Lịch sử chạy", "", "Mọi lần Chạy / Chạy thử / Dump / Restore / Copy DB: lúc nào, database nào, thư mục / file nào, bản svn / git mấy, kết quả.", "HistoryPage",
        [
            new("Bản svn / git", "Nếu thư mục script nằm trong working copy svn (hoặc git) và máy có svn.exe / git.exe: ghi số revision, kèm \"có sửa chưa commit\" nếu file đã sửa. Dùng để trả lời \"DB test đã áp bản nào?\"."),
            new("Mở bản sao lưu", "Lần Chạy có Sao lưu trước khi chạy (cột Thư mục ghi \"có sao lưu trước khi chạy\"): mở thư mục bản sao lưu đó."),
            new("Mở log","File log của lần chạy đó: thứ tự file + kết quả từng file + toàn bộ nhật ký. Lưu ở Data\\History\\Logs cạnh DbTools.exe; giữ 500 lần gần nhất."),
            new("Mở thư mục", "Mở thư mục script của lần chạy đó trong Explorer; với Dump / Restore: mở Explorer chọn sẵn file dump."),
        ]),

        new("Kết nối", "", "Hồ sơ kết nối PostgreSQL (dev, test...), xếp theo cây thư mục. Sửa là tự lưu.", "ConnectionsPage",
        [
            new("Thêm / Nhân bản / Xoá", "Thêm = hồ sơ mới trong thư mục đang đứng (thư mục đang chọn, hoặc thư mục của hồ sơ đang chọn). Nhân bản = chép hồ sơ đang chọn rồi sửa (vd cùng server, khác database), cùng thư mục."),
            new("Thư mục", "Ô Thư mục của hồ sơ: gõ hoặc chọn trong gợi ý, dấu / để lồng nhiều cấp (vd 202604_MCF7/eci), để trống = ở gốc; rời ô hoặc Enter là chuyển. Hoặc kéo-thả trong cây: kéo hồ sơ / thư mục vào thư mục khác (thả lên 1 hồ sơ = vào thư mục của nó, thả xuống khoảng trống dưới cây = ra gốc). Thư mục tự có khi có hồ sơ, tự mất khi hết hồ sơ; không phân biệt hoa thường. Chuột phải thư mục: Thêm hồ sơ vào đây, Đổi tên thư mục (trùng thư mục đã có thì gộp vào). Số cạnh tên = số hồ sơ bên trong. Bấm đúp hoặc mũi tên để mở / thu gọn, nhớ cho lần sau. Trong 1 cấp: thư mục trước, hồ sơ sau, theo tên."),
            new("Tìm", "Ô tìm trên cây: lọc theo tên, host, port, database, user, thư mục; nhiều từ cách nhau bằng dấu cách thì phải có đủ. Rê chuột lên hồ sơ: hiện host:port/database. Ô chọn server ở các trang xếp theo thứ tự cây, ghi \"tên ‹thư mục› (host:port/database)\"."),
            new("Thử kết nối", "Mở kết nối, báo phiên bản PostgreSQL + user@database + schema sẽ tạo đối tượng (theo ô Schema ở trang Chạy) và search_path. Lỗi thì báo lý do (sai mật khẩu, không tới được host...). Sai host / port hoặc tường lửa chặn thì phải chờ hết thời gian chờ kết nối (mặc định 15 giây, đổi ở trang Cài đặt): bấm Huỷ (cạnh vòng xoay) để thôi chờ; đổi sang hồ sơ khác cũng tự huỷ."),
            new("Mật khẩu", "Lưu đã mã hoá theo tài khoản Windows (DPAPI) trong Data\\Config\\connections.json cạnh DbTools.exe. Chép file sang máy / tài khoản khác thì mật khẩu trống, nhập lại."),
            new("Quan trọng (Production)", "Tích cho hồ sơ server thật / khách hàng: danh sách hồ sơ có vạch đỏ + nhãn PRODUCTION, ô chọn server ở mọi trang hiện \"🔴 PRODUCTION · tên\". Chạy (thật), Restore, Copy DB, Ngắt phiên lên hồ sơ này: hộp hỏi lại có khung đỏ, phải gõ lại đúng tên (phân biệt hoa thường) thì nút mới bật - Chạy / Restore gõ tên database đích; Copy gõ tên DB nguồn nếu phải ngắt phiên của nó, còn lại gõ tên DB đích (đích là Production); Ngắt phiên gõ tên database của các phiên (phiên của nhiều DB thì gõ tên hồ sơ). Chạy thử, Kiểm tra, Dump, Thông tin DB, Sinh dữ liệu mẫu không hỏi thêm. Nhân bản hồ sơ giữ dấu Production."),
        ]),
    ];

    /// <summary>Mục hướng dẫn của trang <paramref name="pageTag"/> (không có thì mục đầu).</summary>
    public static HelpSection ForPage(string? pageTag) => Sections.FirstOrDefault(s => s.PageTag == pageTag) ?? Sections[0];
}
